-- Preserve existing receipts and payment snapshots; retire only the old school catalog.
UPDATE console_records SET body=json_set(body,'$.retired',json('true'),'$.active',json('false'),'$.phone_enabled',json('false')), updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE kind='packages' AND json_extract(body,'$.product')='school';
UPDATE plans SET active=0 WHERE product='school';
UPDATE console_records SET body=json_set(body,'$.enabled',json('true'),'$.opening_seconds',600,'$.free_calls_month',2,'$.free_call_seconds',300,'$.basic_enabled',json('false')) WHERE kind='policies' AND json_extract(body,'$.product')='school';
INSERT OR IGNORE INTO console_records(kind,id,body,created_at,updated_at)
SELECT 'policies',id,'{"enabled":true,"product":"school","opening_seconds":600,"free_calls_month":2,"free_call_seconds":300,"basic_enabled":false,"blocked_extension":"/99/8"}',strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM bots WHERE role='teacher';
